FROM tb_user tu
WHERE tu.email = #{email}


INSERT INTO tb_ledger
(
  ledger_year
, ledger_nm
, del_yn
, create_date
, create_user_seq
, update_date
, update_user_seq
) VALUES (
  #{ledgerYear}
, #{ledgerNm}
, 'N'
, CURRENT_TIMESTAMP
, #{createUserSeq}
, CURRENT_TIMESTAMP
, #{updateUserSeq}
)
RETURNING ledger_seq

