INSERT INTO tb_user_ledger
(
  user_seq
, ledger_seq
, ledger_auth
, auth_exit_date
, use_yn
, master_yn
, invite_agree_yn
, show_oneday_yn
, create_date
, create_user_seq
, update_date
, update_user_seq
) VALUES (
  #{userSeq}
, #{ledgerSeq}
, #{ledgerAuth}
, TO_DATE(#{authExitDate},'YYYYMMDD')
, #{useYn}
, #{masterYn}
, #{inviteAgreeYn}
, #{showOnedayYn}
, CURRENT_TIMESTAMP
, #{createUserSeq}
, CURRENT_TIMESTAMP
, #{updateUserSeq}
);
